<style>
    :root {
      --primary: #1E3A8A;
      --primary-dark: #0F172A;
      --primary-accent: #2563EB;
      --gold: #D97706;
      --gold-light: #FEF3C7;
      --gold-deep: #92400E;
      --emerald: #059669;
      --emerald-light: #D1FAE5;
      --bg: #F8FAFC;
      --card-bg: #FFFFFF;
      --text-main: #0F172A;
      --text-sub: #475569;
      --text-muted: #94A3B8;
      --border: #E2E8F0;
      --shadow-sm: 0 2px 4px rgba(0,0,0,0.04);
      --shadow-md: 0 6px 16px rgba(0,0,0,0.08);
      --shadow-lg: 0 12px 30px -4px rgba(0,0,0,0.12);
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Pretendard', 'Noto Sans KR', -apple-system, BlinkMacSystemFont, sans-serif;
      background-color: var(--bg);
      color: var(--text-main);
      line-height: 1.65;
      word-break: keep-all;
      -webkit-font-smoothing: antialiased;
    }

    .container {
      max-width: 880px;
      margin: 0 auto;
      padding: 28px 16px 80px;
    }

    /* Top Tags */
    .top-badge-bar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 18px;
      flex-wrap: wrap;
      gap: 10px;
    }

    .agency-tag {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background-color: #EFF6FF;
      color: #1D4ED8;
      font-weight: 700;
      font-size: 13.5px;
      padding: 6px 16px;
      border-radius: 999px;
      border: 1px solid #DBEAFE;
    }

    .id-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background-color: #0F172A;
      color: #F8FAFC;
      font-weight: 700;
      font-size: 13.5px;
      padding: 6px 16px;
      border-radius: 999px;
      letter-spacing: 0.5px;
    }

    /* Hero Header */
    .hero-card {
      background: linear-gradient(135deg, #0F172A 0%, #1E3A8A 55%, #1E293B 100%);
      color: #FFFFFF;
      padding: 38px 32px;
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      position: relative;
      overflow: hidden;
      margin-bottom: 24px;
    }

    .hero-card::after {
      content: '';
      position: absolute;
      top: -60px;
      right: -60px;
      width: 240px;
      height: 240px;
      background: radial-gradient(circle, rgba(251, 191, 36, 0.15) 0%, rgba(255,255,255,0) 70%);
      border-radius: 50%;
    }

    .hero-badges {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      margin-bottom: 14px;
    }

    .hero-label {
      display: inline-block;
      background-color: rgba(255, 255, 255, 0.18);
      backdrop-filter: blur(8px);
      color: #FDE68A;
      font-size: 13px;
      font-weight: 700;
      padding: 4px 12px;
      border-radius: 6px;
    }

    .hero-label-gold {
      background-color: #F59E0B;
      color: #78350F;
      font-size: 13px;
      font-weight: 800;
      padding: 4px 12px;
      border-radius: 6px;
    }

    .hero-label-emerald {
      background-color: #10B981;
      color: #064E3B;
      font-size: 13px;
      font-weight: 800;
      padding: 4px 12px;
      border-radius: 6px;
    }

    .hero-title {
      font-size: 26px;
      font-weight: 900;
      line-height: 1.38;
      margin-bottom: 12px;
    }

    .hero-subtitle {
      font-size: 15px;
      color: #CBD5E1;
      margin-bottom: 24px;
      font-weight: 400;
    }

    .hero-highlight-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      background: rgba(0, 0, 0, 0.32);
      padding: 18px;
      border-radius: var(--radius-md);
      border: 1px solid rgba(255, 255, 255, 0.12);
    }

    .highlight-item { text-align: center; }
    .highlight-item .label { font-size: 12px; color: #94A3B8; margin-bottom: 5px; }
    .highlight-item .value { font-size: 20px; font-weight: 900; color: #FBBF24; }

    /* Key Summary Alert Box */
    .summary-alert {
      background: linear-gradient(to right, #FEF3C7, #FFFBEB);
      border: 1px solid #FDE68A;
      border-left: 5px solid #F59E0B;
      padding: 18px 20px;
      border-radius: var(--radius-md);
      margin-bottom: 24px;
      font-size: 14.5px;
      color: #78350F;
      line-height: 1.6;
      box-shadow: var(--shadow-sm);
    }

    .summary-alert strong {
      color: #92400E;
    }

    /* Content Cards */
    .section-card {
      background: var(--card-bg);
      border-radius: var(--radius-lg);
      padding: 28px;
      margin-bottom: 24px;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--border);
    }

    .section-title {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 19px;
      font-weight: 800;
      color: var(--text-main);
      margin-bottom: 20px;
      padding-bottom: 12px;
      border-bottom: 2px solid #F1F5F9;
    }

    .section-title span.icon {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 34px;
      height: 34px;
      background-color: #EFF6FF;
      color: #1E3A8A;
      border-radius: 8px;
      font-size: 18px;
    }

    /* Feature Grid */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 16px;
    }

    .feature-box {
      background: #F8FAFC;
      border: 1px solid #E2E8F0;
      border-radius: var(--radius-md);
      padding: 18px;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-box:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
      border-color: #BFDBFE;
    }

    .feature-box .f-title {
      font-size: 15.5px;
      font-weight: 800;
      color: #1E3A8A;
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .feature-box .f-desc {
      font-size: 13.5px;
      color: var(--text-sub);
      line-height: 1.55;
    }

    /* Financial / Yield Box */
    .yield-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
    }

    .yield-item {
      background: #F0FDF4;
      border: 1px solid #DCFCE7;
      border-radius: var(--radius-md);
      padding: 16px;
      text-align: center;
    }

    .yield-item .y-label {
      font-size: 12.5px;
      color: #166534;
      font-weight: 600;
      margin-bottom: 4px;
    }

    .yield-item .y-val {
      font-size: 18px;
      font-weight: 900;
      color: #15803D;
    }

    /* Detailed Spec Table */
    .spec-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
    }

    .spec-table tr { border-bottom: 1px solid #F1F5F9; }
    .spec-table tr:last-child { border-bottom: none; }

    .spec-table th {
      width: 28%;
      padding: 13px 14px;
      background-color: #F8FAFC;
      color: #475569;
      font-weight: 600;
      text-align: left;
      border-right: 1px solid #F1F5F9;
    }

    .spec-table td {
      padding: 13px 16px;
      color: var(--text-main);
      font-weight: 500;
    }

    .spec-table td.strong-price {
      color: #DC2626;
      font-size: 17.5px;
      font-weight: 900;
    }

    .badge-tag {
      display: inline-block;
      padding: 2px 8px;
      background-color: #E0E7FF;
      color: #3730A3;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 700;
      margin-left: 6px;
    }

    .badge-success {
      display: inline-block;
      padding: 2px 8px;
      background-color: #DCFCE7;
      color: #166534;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 700;
      margin-left: 6px;
    }

    /* Narrative Section */
    .narrative-block {
      background: #F8FAFC;
      border-radius: var(--radius-md);
      padding: 20px;
      margin-bottom: 16px;
      border: 1px solid #E2E8F0;
    }

    .narrative-block:last-child {
      margin-bottom: 0;
    }

    .narrative-header {
      font-size: 15.5px;
      font-weight: 800;
      color: #1E3A8A;
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .narrative-text {
      font-size: 14px;
      color: var(--text-sub);
      line-height: 1.65;
    }

    /* QnA Section */
    .qna-box {
      background: #EFF6FF;
      border: 1px solid #DBEAFE;
      border-radius: var(--radius-md);
      padding: 20px;
      margin-top: 14px;
    }

    .qna-q {
      font-size: 15px;
      font-weight: 800;
      color: #1E3A8A;
      margin-bottom: 10px;
      display: flex;
      align-items: flex-start;
      gap: 8px;
    }

    .qna-a {
      font-size: 14px;
      color: #334155;
      line-height: 1.6;
      padding-left: 24px;
    }

    /* Contact Card */
    .contact-card {
      background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
      color: white;
      border-radius: var(--radius-lg);
      padding: 34px 28px;
      text-align: center;
      box-shadow: var(--shadow-lg);
      border: 1px solid #334155;
    }

    .agency-name {
      font-size: 21px;
      font-weight: 800;
      color: #F8FAFC;
      margin-bottom: 6px;
    }

    .agency-sub {
      font-size: 14px;
      color: #94A3B8;
      margin-bottom: 20px;
    }

    .phone-number {
      display: inline-block;
      font-size: 27px;
      font-weight: 900;
      color: #38BDF8;
      letter-spacing: 1px;
      margin-bottom: 20px;
      text-decoration: none;
      transition: transform 0.2s;
    }

    .phone-number:hover {
      transform: scale(1.03);
      color: #7DD3FC;
    }

    .cta-buttons {
      display: flex;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 13px 26px;
      border-radius: var(--radius-md);
      font-size: 15px;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
      border: none;
      transition: all 0.2s;
    }

    .btn-primary {
      background-color: #2563EB;
      color: white;
      box-shadow: 0 4px 14px rgba(37, 99, 235, 0.4);
    }

    .btn-primary:hover {
      background-color: #1D4ED8;
    }

    .btn-outline {
      background-color: rgba(255,255,255,0.08);
      color: white;
      border: 1px solid rgba(255,255,255,0.2);
    }

    .btn-outline:hover {
      background-color: rgba(255,255,255,0.15);
    }

    /* Notice Footer */
    .footer-notice {
      margin-top: 24px;
      text-align: center;
      font-size: 12.5px;
      color: var(--text-muted);
      line-height: 1.6;
    }

    @media (max-width: 640px) {
      .hero-title { font-size: 21px; }
      .hero-card { padding: 24px 20px; }
      .hero-highlight-grid { grid-template-columns: 1fr; gap: 8px; }
      .yield-grid { grid-template-columns: 1fr; }
      .features-grid { grid-template-columns: 1fr; }
      .spec-table th { width: 35%; padding: 10px; }
      .spec-table td { padding: 10px; }
      .phone-number { font-size: 22px; }
    }
  </style>
